def flatten(d: dict) -> dict:
    """Flattens one level of nested dicts, joining keys with a dot.

    {"a": {"b": 1}} -> {"a.b": 1}
    {"c": 2} -> {"c": 2}
    """
    items = []
    for k, v in d.items():
        if isinstance(v, dict):
            new_items = flatten(v).items()
            for nk, nv in new_items:
                items.append((k + "." + nk, nv))
        else:
            items.append((k, v))
    return dict(items)
```

